public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    String dateParts[] = date.split(" ");
    String month = months[Integer.parseInt(dateParts[0]) - 1];
    String day = dateParts[1];
    String year = dateParts[2];

    int weekdayNumber = (Integer.parseInt(dateParts[2]) + Integer.parseInt(dateParts[0]) + Integer.parseInt(dateParts[0]) / 4 - 2 * Integer.parseInt(dateParts[0]) / 100 + Integer.parseInt(dateParts[0]) / 400) % 7;
    String weekday = weekdays[weekdayNumber];

    return month + " " + day + ", " + year + " is a " + weekday;
}

