public int search(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) return mid;
        if (nums[left] <= nums[mid]) {
            if (target < nums[left] || target > nums[mid]) left = mid + 1;
            else right = mid - 1;
        } else {
            if (target > nums[mid] || target < nums[right]) right = mid - 1;
            else left = mid + 1;
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int sortedLength = arr.length;
    int numRemoving = (int) Math.round(arr.length * 0.05);
    int[] sortedArr = Arrays.copyOfRange(arr, numRemoving, sortedLength - numRemoving);
    double sum = 0;
    for (int i : sortedArr) {
        sum += i;
    }
    return sum / (sortedArr.length - 2 * numRemoving);
}

