public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[k + 1];
    fib[0] = 0;
    fib[1] = 1;
    for (int i = 2; i <= k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fib[count];
    }
    return count;
}

