    int[] result = new int[m * n];
    int i = 0, j = 0, k = 0;
    while (i < m && j < n) {
        for (int l = 0; l < n - j; l++) {
            result[k++] = mat[i][j + l];
        }
        i++;
        for (int l = 0; l < m - i; l++) {
            result[k++] = mat[i + l][n - 1];
        }
        j++;
        for (int l = 0; l < m - i && n - j >= 0; l++) {
            result[k++] = mat[i + l][j - 1];
        }
        i++;
        for (int l = 0; l < n - j; l++) {
            result[k++] = mat[m - 1][j + l];
        }
        j++;
    }
    return result;
}

public static int findSmallestInteger(int n) {
    int smallest = -1;
    int[] digits = new int[10];
    int i;

    // count the frequency of each digit
    for (i = 0; i < 10; i++) {
        digits[i] = 0;
    }
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // check if the smallest number is possible
    boolean possible = true;
    for (i = 0; i < 10; i++) {
        if (digits[i] == 0) {
            possible = false;
            break;
        }
    }
    if (!possible) {
        return -1;
    }

    // generate all possible combinations of digits
    for (i = 0; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = smallest * 10 + i;
            digits[i]--;
        }
    }

    return smallest;
}

